({type:`dispositorOf`,point:e});function Y(t,n){switch(t.type){case`planet`:return n.planetLongitude(t.name);case`lot`:return t.name===`fortune`?n.fortune:n.spirit;case`angle`:return t.name===`asc`?n.ascendant:t.name===`mc`?n.mc:t.name===`dsc`?n.dsc:n.ic;case`cusp`:return n.cusps[t.house-1];case`fixed`:return e(t.degree);case`node`:return n.node;case`prenatalSyzygy`:return n.prenatalSyzygy;case`dispositorOf`:{let e=Y(t.point,n),r=D(c(e));return n.planetLongitude(r)}case`signStartOf`:{let r=Y(t.point,n);return Math.floor(e(r)/30)*30}}}function ye(t,n,r){let i=Y(t.base??G(`asc`),n);if(r===`night`&&t.sect===`luminary`)return e(i+Y(t.nightTo,n)-Y(t.nightFrom,n));let a=r===`night`&&t.sect===`reverse`,o=a?t.to:t.from,s=a?t.from:t.to;return e(i+Y(s,n)-Y(o,n))}var X=[{id:`fortune`,label:`Lot of Fortune`,shortLabel:`Fort`,category:`hermetic`,from:U(`Sun`),to:U(`Moon`),sect:`reverse`,citation:`Heliodorus Lots.pdf p.127, p.133; Alcabitius VI.1.1 (al-Qabīsī V.3), pp.282-283`,signification:`Soul, fortune, life, assets, reputation -- traditionally put before all lots.`},{id:`spirit`,label:`Lot of Spirit`,shortLabel:`Spir`,category:`hermetic`,from:U(`Moon`),to:U(`Sun`),sect:`reverse`,citation:`Heliodorus Lots.pdf p.127, p.133; Alcabitius VI.1.2 (al-Qabīsī V.4d), p.284`,signification:`Soul and body, faith, secrets, intentions.`},{id:`courage`,label:`Lot of Courage`,shortLabel:`Crge`,category:`hermetic`,from:U(`Mars`),to:W(`fortune`),sect:`reverse`,citation:`Heliodorus Lots.pdf pp.122,127,133 (Hermes’ Panaretos); Alcabitius VI.1.6 (Gr. Intr. VIII.3, al-Qabīsī V.4f), pp.285-289 -- both traditions agree exactly`,signification:`Boldness, strength, harshness, killing, robbery, cunning.`},{id:`victory`,label:`Lot of Victory`,shortLabel:`Vict`,category:`hermetic`,from:W(`spirit`),to:U(`Jupiter`),sect:`reverse`,citation:`Heliodorus Lots.pdf pp.122,127,133 (explicit day/night confirmation); Alcabitius VI.1.6-289, pp.285-289 -- both traditions agree exactly`,signification:`Honor, blessedness, justice, faith, partnership.`,notes:`Bonatti gives a genuinely different formula for this general topic, "Part of Blessedness"/"Part of Jupiter"/"Part of Triumph and Victory" -- see victoryBonatti.`},{id:`victoryBonatti`,label:`Lot of Victory (Bonatti)`,shortLabel:`Vict-B`,category:`hermetic`,from:U(`Saturn`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.5, 3rd Part of the 2nd house ("Part of Blessedness," also "Part of Jupiter," also "Part of Triumph and Victory"), p.1056, fn.50`,signification:"Honor, blessedness, justice, partnership -- the same broad topic as `victory`, under a Bonatti-specific formula.",notes:`Dykes' fn.50: "Abū Ma'shar does not re-list this Part here, and anyway the formula differs" -- an explicit, source-acknowledged conflict with the Spirit->Jupiter formula both Heliodorus/Paulus and Abū Ma'shar/al-Qabīsī agree on (see \`victory\`). The only Hermetic-lot conflict found across all three traditions now surveyed (Heliodorus, Abū Ma'shar/al-Qabīsī, Bonatti) -- Courage, Nemesis, Fortune, and Spirit remain unanimous.`},{id:`nemesis`,label:`Lot of Nemesis`,shortLabel:`Nems`,category:`hermetic`,from:U(`Saturn`),to:W(`fortune`),sect:`reverse`,citation:`Heliodorus Lots.pdf pp.122,127,133; Alcabitius VI.1.6-289, pp.285-289 -- both traditions agree exactly`,signification:`Memory, self-control, lost/stolen things, conditions of death, imprisonment.`},{id:`erosHellenistic`,label:`Lot of Eros / Love (Hellenistic)`,shortLabel:`Ers-H`,category:`hermetic`,from:W(`spirit`),to:U(`Venus`),sect:`reverse`,citation:`Heliodorus Lots.pdf pp.122,127 (typo-correction footnote confirms Venus, not Mercury),133 -- Hermes’ Panaretos per Paulus/Heliodorus`,signification:`Pleasure, sexual desire, love, marriage-union, concord.`,notes:`Perso-Arabic tradition (Abū Ma’shar/al-Qabīsī) gives a genuinely different formula for this lot -- see erosPersoArabic. The two are offered as separate selectable lots rather than one lot with a flag.`},{id:`erosPersoArabic`,label:`Lot of Eros / Love (Perso-Arabic)`,shortLabel:`Ers-PA`,category:`hermetic`,from:W(`fortune`),to:W(`spirit`),sect:`reverse`,citation:`Alcabitius VI.1.4 (Abbr. VI.6, Gr. Intr. VIII.3.371-390, al-Qabīsī V.4e), pp.285-286`,signification:`Pleasure, sexual desire, love, marriage-union, concord.`,notes:`Hellenistic tradition (Hermes’/Paulus’s Panaretos, per Heliodorus) gives a different formula -- see erosHellenistic. Abū Ma’shar/al-Qabīsī explicitly equate THIS formula with the Lot of Basis and the Lot of Making Friends and Enemies (see lotOfBasis, lotOfMakingFriendsAndEnemies) -- though Heliodorus’s own oldest-manuscript recap treats Basis and this Love lot as two distinct formulas, contradicting that equation.`},{id:`necessityHellenistic`,label:`Lot of Necessity (Hellenistic)`,shortLabel:`Nec-H`,category:`hermetic`,from:U(`Mercury`),to:W(`fortune`),sect:`reverse`,citation:`Heliodorus Lots.pdf pp.122,127,133`,signification:`Poverty, contention, worry, business dealings, cleverness.`,notes:`Perso-Arabic tradition gives a genuinely different formula -- see necessityPersoArabic.`},{id:`necessityPersoArabic`,label:`Lot of Necessity (Perso-Arabic)`,shortLabel:`Nec-PA`,category:`hermetic`,from:W(`spirit`),to:W(`fortune`),sect:`reverse`,citation:`Alcabitius VI.1.5 (Abbr. VI.7), pp.286-287`,signification:`Poverty, contention, worry, business dealings, cleverness.`,notes:`Hellenistic tradition gives a different formula -- see necessityHellenistic. This is the exact night/day mirror image of erosPersoArabic (Fortune<->Spirit swapped) -- Dykes notes the symmetry.`},{id:`lotOfLife`,label:`Lot of Life`,shortLabel:`Life`,category:`hermetic`,from:U(`Jupiter`),to:U(`Saturn`),sect:`reverse`,citation:`Alcabitius VI.2.1, p.290; independently cross-confirmed by Heliodorus Lots.pdf p.125, p.131 (“nicely set forth” list)`,signification:`Natural life, bodily condition.`,notes:`Not one of the core 7 Panaretos lots, but well-attested and cross-confirmed between both traditions. At least 5 further competing "Lot of Life" formulas exist across the corpus (Moon→Venus, Fortune→Venus, Venus→Saturn, Venus→Mercury) and are not implemented -- this is the standard/classical Jupiter→Saturn version.`},{id:`lotOfReleaser`,label:`Lot of the Releaser (Hilaj)`,shortLabel:`Rlsr`,category:`hermetic`,from:ve(),to:U(`Moon`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.4, 4th Part of the 1st house ("Part of the Hilaj"), p.1055, repeated verbatim Ch.16, 1st Part of the "fifth section," p.1086, fn.161-163; Alcabitius VI.2.2, pp.290-292`,signification:`A technical point used for directing/timing danger to life.`,notes:`Reuses the chart's own already-resolved Prenatal Syzygy point (Ptolemy, Tetrabiblos III.2: at a Full Moon/opposition syzygy, whichever luminary's degree was above the horizon at birth governs) rather than re-deriving that conjunction/prevention branching -- Bonatti states the same rule and gives it as non-reversing ("both in the day and in the night"), matching what's implemented here. This does NOT resolve a separate, real dispute Dykes flags: Abū Ma'shar's specific rule for counting a PREVENTIONAL (post-Full-Moon) birth's Releaser may be "probably wrong" relative to Valens (Anthology III.7), who instead counts forward from the natal Moon to the next full moon -- Bonatti's wording carries the identical ambiguity his own translator flags (fn.162) rather than settling it.`},{id:`lotOfFather`,label:`Lot of the Father`,shortLabel:`Fthr`,category:`family`,from:U(`Sun`),to:U(`Saturn`),sect:`reverse`,citation:`Alcabitius VI.2.7, pp.294-295; Heliodorus Lots.pdf p.123, p.134`,signification:`Father's nobility and fortune.`,notes:`The source gives a substitute formula for when Saturn is combust (Sun→Jupiter per Abū Ma’shar, or Mars→Jupiter non-reversing per Paulus) -- not implemented; only the primary formula is computed regardless of Saturn’s combustion status. Bonatti gives a clean, unconditional statement of the Abū Ma'shar branch specifically: "if Saturn is under the rays of the Sun, the Part of the Father is taken, in the day, from the Sun to Jupiter, and reversed at night" (Ch.7, 1st Part of the 4th house, p.1058) -- doesn't resolve the Abū Ma'shar-vs-Paulus disagreement (Bonatti doesn't mention Paulus's alternative here), but strengthens the citation trail for that specific branch if the conditional is ever implemented. The identical Sun→Jupiter reversing formula recurs as an explicit reuse in lotOfHistoriesKnowledge and lotOfWork (both personal/professional category).`},{id:`lotOfMother`,label:`Lot of the Mother`,shortLabel:`Mthr`,category:`family`,from:U(`Venus`),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.2.41, p.318; Heliodorus Lots.pdf p.123, p.127, p.134`,signification:`Condition of mothers.`},{id:`lotOfBrothers`,label:`Lot of Brothers`,shortLabel:`Bros`,category:`family`,from:U(`Saturn`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.2.5, p.293; Heliodorus Lots.pdf p.123, p.127, p.137 -- rare full cross-tradition agreement, including non-reversal`,signification:`Siblings.`},{id:`lotOfBrothersAlt`,label:`Lot of Brothers (al-Andarzaghar)`,shortLabel:`Bros-2`,category:`family`,from:U(`Mercury`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.2.5, p.293 (attributed to al-Andarzaghar, “misattributed to Valens” per Dykes)`,signification:`Siblings (alternate formula for the same topic as lotOfBrothers).`},{id:`lotOfDeathOfBrothers`,label:`Lot of the Death of Brothers`,shortLabel:`BroDth`,category:`family`,from:U(`Sun`),to:G(`mc`),sect:`reverse`,citation:`Alcabitius VI.2.6, p.294`,signification:`Cause and timing of a sibling's death.`},{id:`lotOfFemaleChildrenHermes`,label:`Lot of Female Children (Hermes)`,shortLabel:`Dghtr-H`,category:`family`,from:U(`Moon`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.2.16, p.302`,signification:`Daughters' condition and marriage.`,notes:`Theophilus/Heliodorus give the same two points but with a reversing sect-rule -- see lotOfFemaleChildrenTheophilus.`},{id:`lotOfFemaleChildrenTheophilus`,label:`Lot of Female Children (Theophilus)`,shortLabel:`Dghtr-T`,category:`family`,from:U(`Moon`),to:U(`Venus`),sect:`reverse`,citation:`Heliodorus Lots.pdf p.135 (siding with Theophilus's reversing rule)`,signification:`Daughters' condition and marriage.`,notes:`Same two points as lotOfFemaleChildrenHermes; the disagreement is only about sect-reversal.`},{id:`lotOfMaleChildren`,label:`Lot of Male Children`,shortLabel:`Sons`,category:`family`,from:U(`Moon`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.2.15, pp.301-302 (Hermes/al-Qabīsī); independently confirmed by Heliodorus Lots.pdf p.135 margin note`,signification:`Sex of children.`,notes:`Two further competing formulas exist in the sources ("some Persians" and Theophilus both give Moon→Saturn, with disagreement on reversal) but are not implemented here. Shares its two points (Moon/Jupiter) with lotOfKnowledge (personal category), which uses a different sect-rule for a different topic.`},{id:`lotOfTimeOfChildren`,label:`Lot of the Time of Children`,shortLabel:`ChldTm`,category:`family`,from:U(`Mars`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.2.14, pp.300-301`,signification:`Timing and sex of conception.`},{id:`mensMarriageHermes`,label:`Lot of Men's Marriage (Hermes)`,shortLabel:`MMar-H`,category:`family`,from:U(`Saturn`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.2.21, pp.305-306 (Abū Ma'shar/al-Qabīsī; Paulus's own gender-based rule per Heliodorus p.123 agrees on non-reversal)`,signification:`Quality of a man's marriage.`,notes:`Heliodorus's own later list (p.134) contradicts this with a reversing rule for the identical two points -- an internal inconsistency in that source, not resolved here. Shares its two points with lotOfHope (below), which reverses -- same two planets, different lot.`},{id:`mensMarriageValens`,label:`Lot of Men's Marriage (Valens)`,shortLabel:`MMar-V`,category:`family`,from:U(`Sun`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.2.22, p.306; Heliodorus Lots.pdf p.136 (“according to Valens,” explicit) -- strong cross-tradition match`,signification:`Quality of a man's marriage.`},{id:`womensMarriageHermes`,label:`Lot of Women's Marriage (Hermes)`,shortLabel:`WMar-H`,category:`family`,from:U(`Venus`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.2.23, pp.306-307`,signification:`Quality of a woman's marriage.`,notes:`Formula identical to lotOfCultivation and lotOfDelight (professional category) -- al-Qabīsī states explicitly these are the same lot under three names. Heliodorus's later list (p.134) gives this pair as reversing, contradicting Paulus's own gender-based non-reversing rule (p.123) -- an internal inconsistency in that source.`},{id:`womensMarriageValens`,label:`Lot of Women's Marriage (Valens)`,shortLabel:`WMar-V`,category:`family`,from:U(`Moon`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.2.24, p.307; Heliodorus Lots.pdf p.136 (“according to Valens,” explicit, non-reversing) -- strong cross-tradition match`,signification:`Quality of a woman's marriage.`,notes:`“Certain Persians” reportedly hold this should reverse instead (per Dykes) -- not implemented as a separate variant.`},{id:`lotOfTimeOfMarriage`,label:`Lot of the Time of Marriage`,shortLabel:`MarTm`,category:`family`,from:U(`Sun`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.2.25, pp.307-308`,signification:`Timing of marriage-union.`},{id:`lotOfDelightAndPleasure`,label:`Lot of Delight and Pleasure`,shortLabel:`Pleas`,category:`family`,from:U(`Venus`),to:G(`dsc`),sect:`fixed`,citation:`Alcabitius VI.2.26, p.308`,signification:`Sexual pleasure in marriage.`,notes:`A distinct formula from lotOfCultivation/lotOfDelight (VI.2.18, professional category) despite the near-identical English name. Dykes suspects (per Dorotheus) this should reverse; the source itself gives it as non-reversing, which is what is implemented here.`},{id:`lotOfHope`,label:`Lot of Hope`,shortLabel:`Hope`,category:`family`,from:U(`Saturn`),to:U(`Venus`),sect:`reverse`,citation:`Alcabitius VI.2.44, p.319`,signification:`Attainment of hopes and trust.`,notes:`Shares its two points (Saturn/Venus) with mensMarriageHermes, which is non-reversing -- same two planets, different lot.`},{id:`lotOfFriendsNonReversing`,label:`Lot of Friends (Abū Ma’shar/al-Qabīsī)`,shortLabel:`Frnd-N`,category:`family`,from:U(`Moon`),to:U(`Mercury`),sect:`fixed`,citation:`Alcabitius VI.2.45, p.320 (Abū Ma’shar/al-Qabīsī)`,signification:`Friendship.`,notes:`al-Andarzaghar (cited in the same passage) and Heliodorus (pp.131,135) both favor a reversing rule for the same two points instead -- see lotOfFriendsReversing; Dykes himself sides with the reversing camp.`},{id:`lotOfFriendsReversing`,label:`Lot of Friends (al-Andarzaghar / Heliodorus)`,shortLabel:`Frnd-R`,category:`family`,from:U(`Moon`),to:U(`Mercury`),sect:`reverse`,citation:`Heliodorus Lots.pdf p.131, p.135; al-Andarzaghar per Alcabitius VI.2.45, p.320 (Dykes' preferred reading)`,signification:`Friendship.`},{id:`lotOfMakingFriendsAndEnemies`,label:`Lot of Making Friends and Enemies`,shortLabel:`MkFrnd`,category:`family`,from:W(`fortune`),to:W(`spirit`),sect:`reverse`,citation:`Alcabitius VI.2.46, p.320`,signification:`Making friends and enemies.`,notes:`Formula identical to erosPersoArabic (Fortune↔Spirit) -- al-Qabīsī explicitly states this lot, the Lot of Basis, and the Lot of Eros/Venus are all the same lot under three names.`},{id:`lotOfEnemiesAncients`,label:`Lot of Enemies (the Ancients)`,shortLabel:`Enmy-A`,category:`family`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.2.47, p.321 (“certain ancients”); matches Heliodorus's most common “Enemies” entries (e.g. pp.132,136)`,signification:`Hostility.`},{id:`lotOfEnemiesHermes`,label:`Lot of Enemies (Hermes)`,shortLabel:`Enmy-H`,category:`family`,from:J(K(12)),to:K(12),sect:`fixed`,citation:`Alcabitius VI.2.48, p.321 (Hermes)`,signification:`Hostility (alternate method).`,notes:`Explicitly meant to be used ALONGSIDE lotOfEnemiesAncients, not as a competing replacement for it, per the source’s own instruction.`},{id:`lotOfNumberOfSiblings`,label:`Lot of the Number of Siblings`,shortLabel:`Bro#`,category:`family`,from:U(`Mercury`),to:U(`Saturn`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.6, 2nd Part of the 3rd house, p.1057`,signification:`Specifically the count of siblings, distinct from lotOfBrothers' general condition-of-siblings topic.`},{id:`lotOfOrigins`,label:`Lot of Origins and Condition`,shortLabel:`Orign`,category:`family`,base:U(`Mercury`),from:U(`Saturn`),to:U(`Mars`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.7, 4th Part of the 4th house ("Part of Relations/Kindred/Excellence/Generosity"), pp.1058-1059, AND Ch.11, 4th Part of the 8th house ("Part of the Heavy Place"), p.1070, fn.102 (Bonatti gives it twice, cross-referenced to itself: "Abū Ma'shar said this Part is like the Part of Relatives"); also Alcabitius VI.2.3, p.292, and VI.2.30, p.311`,signification:`Family origins, lineage, and character; also doubles as an indicator of illness in a specific limb, per the "Oppressive/Weighty Place" framing of the same formula.`,notes:`Also called the Lot of the Oppressive/Weighty Place -- one formula under (at least) two names, per both the Alcabitius and Bonatti material, which itself explicitly cross-references the two as identical. The projection point (Mercury's own longitude, not the Ascendant) was previously an open editorial dispute (Dykes reads it as Mercury's own sign-start, i.e. algebraically Mercury's own longitude once combined with the degree-within-sign term this module's base-point mechanism already collapses -- see the module doc comment; Burnett instead reads it projected from the Ascendant) -- Bonatti's independent, twice-repeated confirmation of the Mercury projection resolves that dispute in Dykes' favor, which is what's implemented here.`},{id:`lotOfInheritancesPersian`,label:`Lot of Inheritances (Persian)`,shortLabel:`Inhr-P`,category:`family`,from:U(`Mercury`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.7, 6th Part of the 4th house ("another Part of Inheritances... according to the Persian sages"), p.1059`,signification:`Hereditary matters specifically -- explicitly excludes kingdom, profession, and cultivation, narrower than the Hermes version.`,notes:`A second, competing formula for the same broad "Inheritances" topic lotOfRealEstateWork already carries as one of its (many) aliases (Bonatti's own 5th Part of the 4th house, "according to Hermes") -- Bonatti presents this Persian version explicitly as a distinct, competing method, not a duplicate name for the same computation.`},{id:`lotOfCaptives`,label:`Lot of Captives and the Fettered`,shortLabel:`Captv`,category:`family`,from:J(U(`Sun`)),to:U(`Sun`),sect:`luminary`,nightFrom:J(U(`Moon`)),nightTo:U(`Moon`),citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.9, 4th Part of the 6th house, pp.1062-1063`,signification:`Imprisonment and captivity.`,notes:`Genuinely different formulas for day vs night (the Sun's own dispositor by day, the Moon's own dispositor by night), not a from/to reversal of one formula -- see the module's sect:'luminary' case.`},{id:`lotOfContenders`,label:`Lot of Contenders and Contentions`,shortLabel:`Cntnd`,category:`family`,from:U(`Mars`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 16th Part of the 7th house, p.1068`,signification:`Disputes and quarrels.`,notes:`Shares its two points (Mars/Jupiter) with lotOfTimeOfChildren, which is fixed/non-reversing -- same two planets, different lot.`},{id:`lotOfSkillArrangingMarriage`,label:`Lot of Skill and Ease of Arranging a Marriage`,shortLabel:`MarSkl`,category:`family`,base:U(`Venus`),from:U(`Sun`),to:U(`Moon`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 14th Part of the 7th house, p.1068`,signification:`How easily a marriage can be arranged.`,notes:`Shares its Sun/Moon points with lotOfTimeOfMarriage but is projected from Venus instead of the Ascendant -- a genuinely distinct lot, not a duplicate.`},{id:`lotOfLuxuryFornication`,label:`Lot of Luxury and Men's Fornication`,shortLabel:`Luxur`,category:`family`,from:U(`Venus`),to:U(`Saturn`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 5th Part of the 7th house, pp.1064-1065`,signification:`Men's illicit indulgence.`,notes:`One of a growing Venus↔Saturn (fixed) formula cluster shared with womensMarriageHermes, lotOfCultivation, and (below) lotOfWomensLicentiousness/lotOfWomensSkillTowardMen -- at least 5 distinct traditional names now share this one computation.`},{id:`lotOfWomensLicentiousness`,label:`Lot of Women's Licentiousness and Shamefulness`,shortLabel:`Licent`,category:`family`,from:U(`Venus`),to:U(`Saturn`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 10th Part of the 7th house, p.1066`,signification:`Women's illicit indulgence and shamefulness.`,notes:`Same Venus↔Saturn cluster as lotOfLuxuryFornication -- see its notes.`},{id:`lotOfWomensSkillTowardMen`,label:`Lot of Women's Skill and Cleverness toward Men`,shortLabel:`WSkill`,category:`family`,from:U(`Venus`),to:U(`Saturn`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 8th Part of the 7th house, p.1065`,signification:`Women's cleverness in dealing with men.`,notes:`Same Venus↔Saturn cluster as lotOfLuxuryFornication -- see its notes.`},{id:`lotOfMensCleverness`,label:`Lot of Men's Cleverness and Skill toward Women`,shortLabel:`MSkill`,category:`family`,from:U(`Sun`),to:U(`Venus`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 3rd Part of the 7th house, pp.1064-1065`,signification:`Men's cleverness in dealing with women.`,notes:`Duplicate formula of mensMarriageValens (Sun↔Venus) under a new name -- shared with lotOfMensIntercourse below.`},{id:`lotOfMensIntercourse`,label:`Lot of Men's Sexual Intercourse with Women`,shortLabel:`MIntc`,category:`family`,from:U(`Sun`),to:U(`Venus`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.10, 4th Part of the 7th house, pp.1064-1065`,signification:`Men's sexual relations with women.`,notes:`Same Sun↔Venus duplicate cluster as lotOfMensCleverness -- see its notes.`},{id:`lotOfDeathOfMother`,label:`Lot of the Death of the Mother`,shortLabel:`MthrD`,category:`family`,from:U(`Venus`),to:U(`Saturn`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 14th Part of the 10th house, p.1078`,signification:`Cause and timing of a mother's death.`,notes:`Same two points (Venus/Saturn) as the fixed Venus↔Saturn cluster above (lotOfCultivation, womensMarriageHermes, lotOfLuxuryFornication, etc.), but reversing -- a genuinely distinct lot by sect-behavior alone.`},{id:`lotOfAgreementOfFriends`,label:`Lot of the Agreement of Friends`,shortLabel:`FrAgre`,category:`family`,from:W(`spirit`),to:U(`Mercury`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 8th Part of the 11th house, p.1083`,signification:`Compatibility or discord between friends, or between husband and wife.`},{id:`lotOfFertilityAbundance`,label:`Lot of Fertility and the Abundance of Good in the Home`,shortLabel:`Fertil`,category:`family`,from:U(`Moon`),to:U(`Mercury`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 9th Part of the 11th house, p.1084, fn.150`,signification:`Fertility and domestic abundance.`,notes:`Formula-identical to lotOfFriendsNonReversing (Moon↔Mercury, fixed) -- fn.150 explicitly notes "Abū Ma'shar said this Part is like the Part of Friends."`},{id:`lotOfHonestyOfMind`,label:`Lot of the Honesty of the Mind`,shortLabel:`Honest`,category:`family`,from:U(`Mercury`),to:U(`Sun`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 10th Part of the 11th house, p.1084`,signification:`Honesty of mind and intention.`,notes:`Shares its two points (Mercury/Sun) with lotOfNobles (personal category), which is fixed/non-reversing -- same two planets, different lot.`},{id:`lotOfPraiseGratitude`,label:`Lot of Praise and Gratitude`,shortLabel:`Praise`,category:`family`,from:U(`Jupiter`),to:U(`Venus`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 11th Part of the 11th house, p.1084`,signification:`Being thanked and praised for services rendered.`},{id:`lotOfIntellect`,label:`Lot of Intellect and Reason`,shortLabel:`Intel`,category:`personal`,from:U(`Saturn`),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.2.33, pp.313-314`,signification:`Reasoning, scrutiny, praiseworthy counsel.`,notes:`Shares its two points (Saturn/Moon) with lotOfRealEstateWork (professional category), which is non-reversing -- same two planets, different lot.`},{id:`lotOfKnowledge`,label:`Lot of Knowledge`,shortLabel:`Know`,category:`personal`,from:U(`Moon`),to:U(`Jupiter`),sect:`reverse`,citation:`Alcabitius VI.3.1, p.322`,signification:`Learning.`,notes:`Shares its two points (Moon/Jupiter) with lotOfMaleChildren (family category), which is non-reversing -- same two planets, different lot.`},{id:`lotOfReligion`,label:`Lot of Religion`,shortLabel:`Relig`,category:`personal`,from:U(`Moon`),to:U(`Mercury`),sect:`reverse`,citation:`Alcabitius VI.2.36, p.315`,signification:`Piety, virtue.`,notes:`Dykes flags an erroneous marginal note elsewhere equating "Religion" with the Lot of Spirit -- that equation is wrong and not followed here.`},{id:`lotOfKillingPlanet`,label:`Lot of the Killing Planet (Anaereta)`,shortLabel:`Anrta`,category:`personal`,from:J(G(`asc`)),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.2.28, pp.309-310 (Abū Ma’shar/al-Qabīsī); matches Heliodorus Lots.pdf p.136’s reversing statement for the identical two points`,signification:`Violent-death timing.`,notes:`Heliodorus p.127's own core-lots recap instead states this as non-reversing for the same two points -- an internal self-contradiction in that source. The reversing rule (matching Abū Ma’shar/al-Qabīsī and Heliodorus p.136) is what's implemented here.`},{id:`lotOfRumorsNonReversing`,label:`Lot of Truth and Falsity of Rumors (Abū Ma’shar)`,shortLabel:`Rumr-N`,category:`personal`,from:U(`Mercury`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.2.35, p.314 (Abū Ma’shar)`,signification:`Truth or falsity of rumors.`,notes:`Explicitly said (per Abū Ma’shar, when non-reversing) to be the same formula as lotOfSlaves. al-Qabīsī prefers a reversing rule instead -- see lotOfRumorsReversing; Dykes prefers al-Qabīsī’s reading. Textually messy, with multiple manuscript corruption layers per Dykes.`},{id:`lotOfRumorsReversing`,label:`Lot of Truth and Falsity of Rumors (al-Qabīsī)`,shortLabel:`Rumr-R`,category:`personal`,from:U(`Mercury`),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.2.35, p.314 (al-Qabīsī, Dykes' preferred reading)`,signification:`Truth or falsity of rumors.`},{id:`lotOfReasonAndSense`,label:`Lot of Reason and Sense`,shortLabel:`Rsn`,category:`personal`,from:U(`Mercury`),to:U(`Mars`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.4, 3rd Part of the 1st house ("Part of Thought and Speech"), pp.1054-1055`,signification:`Reasoning faculty, speech.`,notes:`Topically adjacent to lotOfIntellect (Saturn/Moon) but a genuinely different formula. Part of a Mercury↔Mars (reversing) duplicate cluster with lotOfTruthAndGoodWorks and lotOfKingdomKingsDispositors below -- three unrelated names sharing one computation.`},{id:`lotOfInfirmitiesGeneral`,label:`Lot of Infirmities, Separable and Inseparable`,shortLabel:`Infrm`,category:`personal`,from:U(`Mercury`),to:U(`Mars`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.9, 2nd Part of the 6th house, p.1062`,signification:`General illness, as opposed to lotOfChronicIllness's specifically chronic/inseparable defects.`},{id:`lotOfConcernOppression`,label:`Lot of Concern, Oppression, and Destruction`,shortLabel:`Oprss`,category:`personal`,from:U(`Saturn`),to:U(`Mercury`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.11, 5th Part of the 8th house, p.1070`,signification:`Lifelong affliction and oppression.`},{id:`lotOfHistoriesKnowledge`,label:`Lot of Histories and Knowledge, Rumors and Stories`,shortLabel:`Histry`,category:`personal`,from:U(`Sun`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.12, 6th Part of the 9th house, pp.1072-1073, fn.106`,signification:`Historical/general knowledge, rumors, and stories.`,notes:`fn.106: "Abū Ma'shar said this Part agrees with the Part of the Father, if Saturn were under the rays" -- i.e. this reuses the Sun→Jupiter (reversing) formula lotOfFather's own notes cite as Abū Ma'shar's combust-Saturn substitute. A third member of that Sun↔Jupiter reuse cluster, alongside lotOfWork (professional category).`},{id:`lotOfNobles`,label:`Lot of Nobles`,shortLabel:`Noble`,category:`personal`,from:U(`Mercury`),to:U(`Sun`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 6th Part of the 10th house, p.1075`,signification:`Nobility of rank.`,notes:`Shares its two points (Mercury/Sun) with lotOfHonestyOfMind (family category), which reverses -- same two planets, different lot.`},{id:`lotOfSoldiersMinisters`,label:`Lot of Soldiers and Ministers`,shortLabel:`Soldr`,category:`personal`,from:U(`Mars`),to:U(`Saturn`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 7th Part of the 10th house, p.1075`,signification:`Military or administrative service.`},{id:`lotOfKnownAmongMen`,label:`Lot of One Known and Honored Among Men`,shortLabel:`Known`,category:`personal`,from:W(`fortune`),to:U(`Sun`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 3rd Part of the 11th house, p.1081`,signification:`Public renown.`},{id:`lotOfLuckAndProfit`,label:`Lot of Luckiness and Profit`,shortLabel:`Luck`,category:`personal`,from:W(`fortune`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.14, 4th Part of the 11th house, p.1081`,signification:`Financial luck.`,notes:`Structurally parallel to victory (Spirit→Jupiter) but uses Fortune instead of Spirit -- a related but distinct formula.`},{id:`lotOfCleverness`,label:`Lot of Cleverness and Sharpness of Learning`,shortLabel:`Clevr`,category:`personal`,from:U(`Mercury`),to:W(`spirit`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 5th Part of the "fifth section," pp.1087-1088`,signification:`All-around mental aptitude and memory.`},{id:`lotOfTruthAndGoodWorks`,label:`Lot of Truth and Good Works`,shortLabel:`Truth`,category:`personal`,from:U(`Mercury`),to:U(`Mars`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 10th Part of the "fifth section," p.1090, fn.182`,signification:`Truthfulness and good works.`,notes:`Same Mercury↔Mars formula as lotOfReasonAndSense -- fn.182 confirms: "Abū Ma'shar said this Part is like the Part of Reason and Sense."`},{id:`lotOfKingdomKingsDispositors`,label:`Lot of the Kingdom and Kings and Dispositors`,shortLabel:`KKngD`,category:`personal`,from:U(`Mercury`),to:U(`Mars`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 3rd Part of the 10th house, p.1075`,signification:`Kingship and its dispositors.`,notes:`Third name for the Mercury↔Mars (reversing) cluster shared with lotOfReasonAndSense and lotOfTruthAndGoodWorks.`},{id:`lotOfRepayment`,label:`Lot of Repayment`,shortLabel:`Repay`,category:`personal`,from:U(`Mars`),to:U(`Sun`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 9th Part of the "fifth section," p.1090`,signification:`Whether the native repays favors done for him.`},{id:`lotOfWarfareBoldness`,label:`Lot of Warfare and Boldness`,shortLabel:`Warfr`,category:`personal`,from:U(`Saturn`),to:U(`Moon`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 3rd Part of the "fifth section," p.1087, fn.166-168`,signification:`Military prowess and boldness.`,notes:`Same two points as lotOfIntellect. Bonatti's own source (per fn.166-168) cross-references this to BOTH lotOfIntellect (reversing) and lotOfRealEstateWork (fixed) as "like" both -- but those two have different sect-behavior from each other, so the cross-reference is only true by day. This is an independent second attestation of the identical imprecision Dykes already flagged for the Alcabitius material (see lotOfRealEstateWork's citation), confirming it's original to the Abū Ma'shar tradition rather than a one-off manuscript artifact.`},{id:`lotOfBoldnessStrengthRulership`,label:`Lot of Boldness and Strength and Rulership`,shortLabel:`BldSt`,category:`personal`,from:J(G(`asc`)),to:U(`Moon`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 4th Part of the "fifth section," p.1087`,signification:`Bodily vigor and rulership.`,notes:`Same formula as lotOfKillingPlanet (Anaereta) -- Lord of Ascendant→Moon, reversing -- but reused by Bonatti for a completely different topic (bodily vigor/rulership vs. violent death).`},{id:`lotOfInvestigation`,label:`Lot of the Investigation of a Matter`,shortLabel:`Invstg`,category:`personal`,base:U(`Mercury`),from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.16, 6th Part of the "fifth section," pp.1088-1089`,signification:`Whether an unknown or uncertain matter will be perfected, destroyed, or delayed.`,notes:`Same two points (Saturn/Mars) as lotOfChronicIllness and lotOfEnemiesAncients, but genuinely distinct due to its unusual Mercury-projection base.`},{id:`lotOfBasis`,label:`Lot of Basis`,shortLabel:`Basis`,category:`physical`,from:W(`fortune`),to:W(`spirit`),sect:`reverse`,citation:`Alcabitius VI.1.4, pp.285-286 (Abū Ma’shar/al-Qabīsī, who equate it with Eros/Venus and Making Friends and Enemies); Heliodorus Lots.pdf p.133 gives it as its own distinct formula in the oldest-manuscript recap`,signification:`Facial appearance, resemblance to parents, soundness of body.`,notes:`Abū Ma’shar/al-Qabīsī state this is the SAME formula as erosPersoArabic and lotOfMakingFriendsAndEnemies (Fortune↔Spirit) -- but Heliodorus's own cleanest, oldest-manuscript recap (p.133) treats Basis and the Desire/Love lot as two separate formulas, contradicting that equation. Separately, Heliodorus p.128 also uses “Basis” to mean simply the Ascendant itself -- an unrelated third sense of the word, not implemented as a distinct lot since it isn't a calculation. Bonatti gives this same formula as "Part of Durability and Stability"/"Part of the Security of the Ascendant" (Ch.4, pp.1052-1053) and reports Abū Ma'shar's Eros equation there too -- but Bonatti's own translator (fn.41) explicitly disagrees with that equation ("It is not the same"), an independent voice on the same side as Heliodorus's p.133 recap against Abū Ma'shar/al-Qabīsī's reading.`},{id:`lotOfChronicIllness`,label:`Lot of Chronic Illness`,shortLabel:`Illns`,category:`physical`,from:U(`Saturn`),to:U(`Mars`),sect:`reverse`,citation:`Alcabitius VI.2.19, pp.303-304`,signification:`Disease, chronic illness.`,notes:`Shares its two points (Saturn/Mars) with lotOfEnemiesAncients, which is non-reversing -- same two planets, different lot.`},{id:`lotOfDeath`,label:`Lot of Death`,shortLabel:`Death`,category:`physical`,base:U(`Saturn`),from:U(`Moon`),to:K(8),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.11, 1st Part of the 8th house ("Part of Death"), p.1069; independently cross-confirmed by Alcabitius VI.2.27, pp.308-309 (same compound description: Moon to the 8th cusp, plus Saturn's own degree within its sign, projected from Saturn's own sign-start -- algebraically identical to base=Saturn's own longitude, see the module doc comment above)`,signification:`Manner of death.`,notes:`Bonatti states this explicitly "in the day and the night" -- non-reversing, as implemented here.`},{id:`lotOfAssets`,label:`Lot of Assets`,shortLabel:`Asset`,category:`professional`,from:J(K(2)),to:K(2),sect:`fixed`,citation:`Alcabitius VI.2.4, pp.292-293; structurally confirmed by Heliodorus Lots.pdf p.134 (“Livelihood”)`,signification:`Livelihood, personal wealth.`,notes:`A 2nd-house 'money' lot, distinct from the dedicated Commodity Lots category, which forecast market prices rather than personal wealth.`},{id:`lotOfRealEstateWork`,label:`Lot of Real Estate and the Native's Work`,shortLabel:`Estate`,category:`professional`,from:U(`Saturn`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.2.10 p.297, VI.2.40 pp.317-318, VI.3.2 p.322 -- explicitly stated by the source to be one formula shared by three names (Real Estate, the Native’s Own Work/Authority, and Heroism and Bravery)`,signification:`Real estate, career and handiwork, achievement through one's own work.`,notes:`Shares its two points (Saturn/Moon) with lotOfIntellect (personal category), which reverses -- same two planets, different lot.`},{id:`lotOfCultivation`,label:`Lot of Cultivation of the Earth`,shortLabel:`Cultiv`,category:`professional`,from:U(`Venus`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.2.11, p.298`,signification:`Farming and agricultural success.`,notes:`Formula identical to womensMarriageHermes and lotOfDelight (VI.2.18) -- al-Qabīsī states explicitly these are the same lot under three names.`},{id:`lotOfTravel`,label:`Lot of Travel (Foreign)`,shortLabel:`Trvl`,category:`professional`,from:J(K(9)),to:K(9),sect:`fixed`,citation:`Alcabitius VI.2.31, p.312; structurally confirmed by Heliodorus Lots.pdf p.136 (“Foreign”)`,signification:`Foreign travel and its condition.`},{id:`lotOfNavigation`,label:`Lot of Navigation`,shortLabel:`Navig`,category:`professional`,from:U(`Saturn`),to:q(105),sect:`reverse`,citation:`Alcabitius VI.2.32, pp.312-313; cross-confirmed by Heliodorus Lots.pdf p.137 (“Sailing”)`,signification:`Sea travel.`},{id:`lotOfSlaves`,label:`Lot of Slaves`,shortLabel:`Slave`,category:`professional`,from:U(`Mercury`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.2.20, pp.304-305 (Abū Ma’shar/al-Qabīsī)`,signification:`Servants and staff.`,notes:`Heliodorus's parallel material gives at least 3 further competing formulas (Mars→Moon, Venus→Moon later corrected to Mercury→Moon, and a reversing Mercury→Moon) -- not implemented. Also explicitly said (per Abū Ma’shar) to be the same formula as lotOfRumorsNonReversing.`},{id:`lotOfJobAndAuthority`,label:`Lot of a Job and Authority (Valens)`,shortLabel:`Job`,category:`professional`,from:U(`Sun`),to:G(`mc`),sect:`fixed`,citation:`Alcabitius VI.2.42, p.319 (Valens)`,signification:`Career and authority.`},{id:`lotOfCauseOfKingdom`,label:`Lot of the Cause of a Kingdom`,shortLabel:`CauseK`,category:`professional`,base:U(`Jupiter`),from:U(`Sun`),to:G(`mc`),sect:`fixed`,citation:`Alcabitius VI.2.43, p.319`,signification:`The underlying cause of a native's authority and rank.`},{id:`lotOfKingdomAuthority`,label:`Lot of the Kingdom and Authority`,shortLabel:`Kngdm`,category:`professional`,from:U(`Mars`),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.2.38, p.316`,signification:`Kingship, leadership.`,notes:`One of at least three unrelated "Kingdom"-labeled formulas in the source.`},{id:`lotOfPowerSupremacy`,label:`Lot of Power, Kingdom, or Supremacy`,shortLabel:`Pwr`,category:`professional`,from:U(`Sun`),to:U(`Saturn`),sect:`reverse`,citation:`Alcabitius VI.2.39, p.317`,signification:`Authority, rank.`,notes:`Conditionally identical to the Lot of the Father when Saturn is not combust (both Sun→Saturn); the source’s further conditional substitute for when Saturn IS combust (Sun→Jupiter) is not implemented -- only the primary formula is.`},{id:`lotOfWisdomAndJudgment`,label:`Lot of Wisdom and Judgment`,shortLabel:`Wisdm`,category:`professional`,base:U(`Mercury`),from:U(`Saturn`),to:U(`Jupiter`),sect:`reverse`,citation:`Alcabitius VI.2.34/VI.3.1, pp.313-314, per Dykes' own emendation (fn80); independently confirmed by Bonatti Liber Astronomiae Tr.8.2 Ch.12, 5th Part of the 9th house ("Part of Wisdom and Patience"), pp.1072-1073, which states the Mercury projection directly rather than as an emendation`,signification:`Wisdom, judgment, patience.`,notes:`Dykes believed an Arabic scribe swapped this lot's projection point with the Lot of Peace/Concord of Armies' (Mercury vs. the Ascendant) and silently corrected both in his translation of Alcabitius -- his own emendation, not a manuscript-certain reading there. Bonatti's independent, non-emended citation of the same Mercury projection is a genuine third-source confirmation that resolves the uncertainty in favor of Mercury.`},{id:`lotOfGrandfathers`,label:`Lot of Grandfathers`,shortLabel:`GrndF`,category:`professional`,from:J(U(`Sun`)),to:U(`Saturn`),sect:`reverse`,citation:`Alcabitius VI.2.9, pp.296-297; special-case branches spelled out by Bonatti Liber Astronomiae Tr.8.2 Ch.7, 3rd Part of the 4th house, pp.1058-1059`,signification:`Condition of grandfathers.`,notes:`The source gives further special-case branches not implemented here -- Bonatti spells them out explicitly: if the Sun is in Leo (its own domicile), project from 0° Leo instead of the Lord of the Sun's sign; if the Sun is in Capricorn or Aquarius (Saturn's domicile), use the Sun's own longitude directly in place of its dispositor. Only the general-case formula (Lord of the Sun's sign → Saturn) is computed here.`},{id:`lotOfMoneylenders`,label:`Lot of Moneylenders`,shortLabel:`Moneyl`,category:`professional`,from:U(`Saturn`),to:U(`Mercury`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.5 (2nd-house material), p.1056`,signification:`Usury and lending.`},{id:`lotOfCollection`,label:`Lot of Collection`,shortLabel:`Collct`,category:`professional`,from:U(`Mercury`),to:U(`Venus`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.5, 4th Part of the 2nd house, p.1056`,signification:`Finding lost or dispersed things (on roads, in camps, at the seashore, in mountains, by digging); recovering fled, forgotten, or lost items.`,notes:`Distinct from nemesis's lost-and-stolen-things signification -- different formula, different points. Duplicated under a second name, lotOfBusinessmenHandiwork, per Bonatti's own cross-reference.`},{id:`lotOfBusinessmenHandiwork`,label:`Lot of Businessmen and Those Working with Their Hands`,shortLabel:`Bizns`,category:`professional`,from:U(`Mercury`),to:U(`Venus`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 9th Part of the 10th house, p.1078, fn.125`,signification:`Manual trades and business dealings.`,notes:`Formula-identical to lotOfCollection -- fn.125: "Abū Ma'shar said this Part is like the Part of Collection," an explicit Bonatti-internal duplicate.`},{id:`lotOfWork`,label:`Lot of Work`,shortLabel:`Work`,category:`professional`,from:U(`Sun`),to:U(`Jupiter`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.13, 11th Part of the 10th house, p.1078, fn.129`,signification:`One's work and occupation.`,notes:`fn.129: "Abū Ma'shar said this Part is like the Part of Fathers if Saturn were under the rays" -- a third member of the Sun↔Jupiter reuse cluster alongside lotOfHistoriesKnowledge (personal category) and lotOfFather's own combust-Saturn substitute (see lotOfFather's notes).`},{id:`lotOfExaltation`,label:`Lot of Exaltation and Nobility`,shortLabel:`Exalt`,category:`professional`,from:U(`Sun`),to:q(19),sect:`luminary`,nightFrom:U(`Moon`),nightTo:q(33),citation:`Alcabitius VI.2.37, pp.315-316; independently confirmed TWICE by Bonatti Liber Astronomiae Tr.8.2 (Ch.7, 8th Part of the 4th house, p.1060, fn.57, "per al-Qabīsī"; Ch.13, 1st Part of the 10th house, p.1074); Heliodorus Lots.pdf p.126, p.133, p.136`,signification:`Nobility and rank; also doubles as a paternity/legitimacy indicator per Alcabitius.`,notes:`Day and night are genuinely different formulas (each luminary's own exaltation degree), not a reversal of one formula -- see the module's sect:'luminary' case. Heliodorus p.133's night formula gives the Moon's exaltation as "3rd of Scorpio," almost certainly a scribal error (Scorpio is nowhere else the Moon's exaltation in classical astrology) -- Bonatti's independent double confirmation of 3° Taurus resolves the question in Taurus's favor, which is what's implemented here.`},{id:`commodityFood`,label:`Commodity Lot: Food / Wheat`,shortLabel:`Wheat`,category:`commodity`,from:U(`Sun`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 1`,signification:`Price of food/wheat.`},{id:`commodityWater`,label:`Commodity Lot: Water`,shortLabel:`Water`,category:`commodity`,from:U(`Moon`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 2`,signification:`Price/abundance of water.`},{id:`commodityBarley`,label:`Commodity Lot: Barley`,shortLabel:`Barly`,category:`commodity`,from:U(`Moon`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 3`,signification:`Price of barley.`},{id:`commodityChickpeas`,label:`Commodity Lot: Chickpeas`,shortLabel:`Chkpea`,category:`commodity`,from:U(`Venus`),to:U(`Sun`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 4`,signification:`Price of chickpeas.`},{id:`commodityLentils`,label:`Commodity Lot: Lentils`,shortLabel:`Lentl`,category:`commodity`,from:U(`Mars`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 5`,signification:`Price of lentils.`},{id:`commodityEgyptianBeans`,label:`Commodity Lot: Egyptian Beans`,shortLabel:`EgBean`,category:`commodity`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 6`,signification:`Price of Egyptian beans.`},{id:`commodityIndianPeas`,label:`Commodity Lot: Indian Peas`,shortLabel:`InPeas`,category:`commodity`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 7`,signification:`Price of Indian peas.`,notes:`Identical formula to commodityEgyptianBeans -- likely a scribal duplication in the source, reported as given rather than silently merged.`},{id:`commodityDates`,label:`Commodity Lot: Dates`,shortLabel:`Dates`,category:`commodity`,from:U(`Sun`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 8`,signification:`Price of dates.`},{id:`commodityHoney`,label:`Commodity Lot: Honey`,shortLabel:`Honey`,category:`commodity`,from:U(`Moon`),to:U(`Sun`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 9`,signification:`Price of honey.`},{id:`commodityRice`,label:`Commodity Lot: Rice`,shortLabel:`Rice`,category:`commodity`,from:U(`Jupiter`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 10`,signification:`Price of rice.`},{id:`commodityOlives`,label:`Commodity Lot: Olives`,shortLabel:`Olive`,category:`commodity`,from:U(`Mercury`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 11`,signification:`Price of olives.`},{id:`commodityGrapes`,label:`Commodity Lot: Grapes`,shortLabel:`Grape`,category:`commodity`,from:U(`Saturn`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 12`,signification:`Price of grapes.`},{id:`commodityCotton`,label:`Commodity Lot: Cotton`,shortLabel:`Cottn`,category:`commodity`,from:U(`Mercury`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 13`,signification:`Price of cotton.`},{id:`commoditySesame`,label:`Commodity Lot: Sesame`,shortLabel:`Sesme`,category:`commodity`,from:U(`Saturn`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 14`,signification:`Price of sesame.`,notes:`The source gives an explicit alternative formula, Saturn→Venus, not implemented as a separate entry.`},{id:`commodityMelons`,label:`Commodity Lot: Watermelons / Melons`,shortLabel:`Melon`,category:`commodity`,from:U(`Mercury`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 15`,signification:`Price of watermelons/melons.`},{id:`commodityAcidicFoods`,label:`Commodity Lot: Acidic Foods (general)`,shortLabel:`Acid`,category:`commodity`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 16`,signification:`Price of acidic foods generally.`},{id:`commoditySweetFoods`,label:`Commodity Lot: Sweet Foods (general)`,shortLabel:`Sweet`,category:`commodity`,from:U(`Sun`),to:U(`Venus`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 17`,signification:`Price of sweet foods generally.`,notes:`Identical formula to commodityDates.`},{id:`commodityPungentFoods`,label:`Commodity Lot: Pungent/Spicy Foods (general)`,shortLabel:`Spicy`,category:`commodity`,from:U(`Mars`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 18`,signification:`Price of pungent/spicy foods generally.`},{id:`commodityBitterFoods`,label:`Commodity Lot: Bitter Foods (general)`,shortLabel:`Bitter`,category:`commodity`,from:U(`Mercury`),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 19`,signification:`Price of bitter foods generally.`},{id:`commodityPurgativeSweetMedicines`,label:`Commodity Lot: Purgative & Sweet Medicines`,shortLabel:`MedSw`,category:`commodity`,from:U(`Sun`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.5, p.328, item 20`,signification:`Price of purgative & sweet medicines.`},{id:`commodityPurgativeAcidicMedicines`,label:`Commodity Lot: Purgative & Acidic Medicines`,shortLabel:`MedAc`,category:`commodity`,from:U(`Saturn`),to:U(`Jupiter`),sect:`fixed`,citation:`Alcabitius VI.5, p.329, item 21`,signification:`Price of purgative & acidic medicines.`,notes:`Duplicates one of commoditySesame’s two source alternatives (Saturn→Jupiter).`},{id:`commodityPurgativeSaltyMedicines`,label:`Commodity Lot: Purgative & Salty Medicines`,shortLabel:`MedSl`,category:`commodity`,from:U(`Mars`),to:U(`Moon`),sect:`fixed`,citation:`Alcabitius VI.5, p.329, item 22`,signification:`Price of purgative & salty medicines.`},{id:`commodityPoisons`,label:`Commodity Lot: Poisons`,shortLabel:`Poisn`,category:`commodity`,from:_e(),to:U(`Saturn`),sect:`fixed`,citation:`Alcabitius VI.5, p.329, item 23`,signification:`Poisons.`,notes:`The only lot in the entire corpus using the lunar Node as a point.`},{id:`commodityOnions`,label:`Commodity Lot: Onions`,shortLabel:`Onion`,category:`commodity`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1094, fn.190`,signification:`Price of onions.`,notes:`fn.190: "Not in al-Qabīsī, but al-Bīrūnī lists the Lot of Beans and the Lot of Onions as being the same" -- duplicate formula of commodityEgyptianBeans/commodityIndianPeas (Saturn→Mars).`},{id:`commodityGreenPeas`,label:`Commodity Lot: Green Peas`,shortLabel:`GrnPea`,category:`commodity`,from:U(`Saturn`),to:U(`Mars`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1094`,signification:`Price of green peas.`,notes:`Bonatti states this explicitly shares the identical computed place as commodityOnions -- another member of the Saturn→Mars duplicate cluster.`},{id:`commoditySugar`,label:`Commodity Lot: Sugar`,shortLabel:`Sugar`,category:`commodity`,from:U(`Mercury`),to:U(`Venus`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1095, fn.191`,signification:`Price of sugar.`,notes:`New name, but formula-identical to commodityCotton (Mercury→Venus). fn.191: "Not in al-Qabīsī, but al-Bīrūnī lists a Lot of Sugar as being calculated the opposite way: from Venus to Mercury (and the reverse by night)" -- a genuinely different, explicitly sect-reversing al-Bīrūnī variant, not implemented as a separate entry.`},{id:`commoditySilk`,label:`Commodity Lot: Silk and Other Woven Things`,shortLabel:`Silk`,category:`commodity`,from:U(`Mercury`),to:U(`Venus`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1096, fn.194`,signification:`Price of silk and woven goods.`,notes:`New name, duplicate formula of commodityCotton/commoditySugar (Mercury→Venus). fn.194: al-Bīrūnī calls this the "Lot of Raw Silk, Cotton."`},{id:`commodityNuts`,label:`Commodity Lot: Nuts`,shortLabel:`Nuts`,category:`commodity`,from:U(`Mercury`),to:U(`Mars`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1096, fn.193`,signification:`Price of nuts.`,notes:`Genuinely new formula, not present in al-Qabīsī's 23. fn.193: "I do not find this in al-Qabīsī, and al-Bīrūnī's is calculated from Mars to Venus" -- a third, different formula per that source, not independently verified (al-Bīrūnī's own text isn't part of the scanned material) and not implemented.`},{id:`commoditySaltedThings`,label:`Commodity Lot: Salted Things`,shortLabel:`Salted`,category:`commodity`,from:U(`Mars`),to:U(`Moon`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1097, fn.200`,signification:`Price of salted foods.`,notes:`New name (as a food commodity) for a formula already in the catalog under a medicine-market framing -- fn.200: "This is al-Qabīsī's Lot of Purgative and Salty Medicines" = commodityPurgativeSaltyMedicines's formula reused. Bonatti's own text also lists a near-identical "Part of Salted Medicines" entry one page later using the same formula -- a Bonatti-internal duplicate, not a transcription error here.`},{id:`commodityWetnessDryness`,label:`Commodity Lot: Wetness and Dryness`,shortLabel:`WetDry`,category:`commodity`,from:U(`Moon`),to:U(`Venus`),sect:`reverse`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1097, fn.199`,signification:`General wetness/dryness conditions affecting crops and markets.`,notes:`Genuinely new formula, not in al-Qabīsī or al-Bīrūnī per fn.199. Notably the ONE commodity-type lot in the entire corpus surveyed across all seven source PDFs (four original plus three Bonatti) where a night-reversal rule is explicitly stated -- implemented with sect:"reverse" rather than the "fixed" every other commodity lot uses, since here the source is not silent.`},{id:`commodityDispositionOfYear`,label:`Commodity Lot: Disposition of the Year`,shortLabel:`YearDs`,category:`commodity`,from:U(`Moon`),to:U(`Mercury`),sect:`fixed`,citation:`Bonatti Liber Astronomiae Tr.8.2 Ch.18, p.1099, fn.204`,signification:`A general "meta" indicator said to comprehend all the other commodity lots at once.`,notes:`Genuinely new formula. fn.204: "I am not sure what Bonatti's source for this Part is" -- likely original to Bonatti, not sourced to al-Qabīsī or al-Bīrūnī.`},{id:`mundaneKingdomCommand1`,label:`Mundane Lot of Kingdom & Command I`,shortLabel:`MKng1`,category:`professional-mundane`,from:U(`Mars`),to:U(`Moon`),sect:`reverse`,citation:`Alcabitius VI.4 ("Mundane Lots: al-Qabīsī"), pp.324-325`,signification:`A ruler's mundane authority and command.`,notes:`Source computes this on the Ascendant of the mundane Saturn-Jupiter conjunction chart, not a natal chart; adapted here to the natal Ascendant. Once adapted, this is numerically identical to lotOfKingdomAuthority (professional category) -- the two formulas’ only distinguishing feature in the source (which chart’s Ascendant is used) disappears under natal adaptation. Kept as a separate selectable entry because its traditional signification (a ruler’s mundane authority) differs from the natal lot’s (a native’s personal authority), even though the computed degree coincides.`},{id:`mundaneKingdomCommand3`,label:`Mundane Lot of Kingdom & Command III`,shortLabel:`MKng3`,category:`professional-mundane`,base:U(`Jupiter`),from:U(`Sun`),to:G(`mc`),sect:`fixed`,citation:`Alcabitius VI.4, p.326`,signification:`The underlying mundane cause of a kingdom or regime.`,notes:`Same natal-adaptation caveat as mundaneKingdomCommand1. Once adapted to natal, numerically identical to lotOfCauseOfKingdom (professional category) for the same reason -- kept separate for its distinct traditional (mundane/dynastic) signification.`}];function be(e,t){let n=t=>e.planets.find(e=>e.name===t).longitude,r=e.points.find(e=>e.name===`Part of Fortune`).longitude,i=e.points.find(e=>e.name===`Part of Spirit`).longitude,a=e.points.find(e=>e.name===`North Node`).longitude,o=e.points.find(e=>e.name===`Prenatal Syzygy`).longitude,s={ascendant:e.angles.ascendant,mc:e.angles.midheaven,dsc:e.angles.descendant,ic:e.angles.imumCoeli,cusps:e.cusps,planetLongitude:n,fortune:r,spirit:i,node:a,prenatalSyzygy:o},c={};for(let e of X)c[e.id]=ye(e,s,t);return c}function Z(t){let n=e=>Math.abs(t.reduce((t,n,r)=>t+e(r),0)-360)<1e-6;return n(n=>e(t[(n+1)%12]-t[n]))?`forward`:n(n=>e(t[n]-t[(n+1)%12]))?`backward`:`mixed`}function Q(t,n){let r=e(t),i=Z(n)===`backward`;for(let t=0;t<12;t++){let a=n[t],o=n[(t+1)%12],s=e(i?a-o:o-a);if(e(i?a-r:r-a)<s||s===0)return t+1}return 12}function xe(t,n){if(n===0)return t;let r=Z(t)===`backward`?1:-1;return t.map(t=>e(t+r*n))}function $(t,n,r,i=`alcabitius`,a){let c=s(t),l=u(t),p=a??d(t,r),m=h[i](p,n,l),{cusps:v}=m,y=m.unreliable||Z(v)===`mixed`,b={...m.angles,..._(p,n,l)},x=c.map(e=>Q(e.longitude,v)),S=c.find(e=>e.name===`Sun`).longitude,C=c.find(e=>e.name===`Moon`).longitude,w=L(Q(S,v)),T=o(t),{fortune:E,spirit:D}=he(b.ascendant,S,C,w),O=f(t),k,A;O.type===`conjunction`?(k=O.moonLongitude,A=`conjunction`):L(Q(O.sunLongitude,v))===`day`?(k=O.sunLongitude,A=`sun-prevention`):(k=O.moonLongitude,A=`moon-prevention`);let j=[{name:`North Node`,longitude:T},{name:`South Node`,longitude:e(T+180)},{name:`Part of Fortune`,longitude:E},{name:`Part of Spirit`,longitude:D},{name:`Prenatal Syzygy`,longitude:k,syzygyKind:A}],M=j.map(e=>Q(e.longitude,v));return{utcDate:t,latitude:n,longitude:r,planets:c,angles:b,cusps:v,housesUnreliable:y,polar:g(p,n,l),planetHouses:x,points:j,pointHouses:M}}function Se(e,t=`alcabitius`){return $(m(e),e.latitude,e.longitude,t)}var Ce={cuspOffsetDegrees:0,triplicityScheme:`dorothean`,dignitiesApplyPeregrinePenalty:!0,hylegMethod:`umar-al-tabari`,almutenMethod:`ibn-ezra`,almutenIncludeDayHourBonus:!1,almutenTriplicityCountMode:`all`,triplicityCountMode:`all`,temperamentMethod:`ptolemaic`,temperamentTriplicityCountMode:`all`,wealthMethod:`janus`,wealthQuadrantHouses:!1,professionScoring:`essential-accidental`},we=`astro-app:chart-session`;function Te(e){localStorage.setItem(we,JSON.stringify(e))}function Ee(){let e=localStorage.getItem(we);if(!e)return null;try{return JSON.parse(e)}catch{return null}}var De=new Set([`walk`,`horary`,`electional`]);function Oe(e){let{birthInput:t,walkDateIso:n,chartMode:r}=e;if(!n||!De.has(r))return t;let i=new Date(n);if(Number.isNaN(i.getTime()))return t;let a=new Date(i.getTime()+t.utcOffsetMinutes*6e4),o=a.getUTCSeconds();return{year:a.getUTCFullYear(),month:a.getUTCMonth()+1,day:a.getUTCDate(),hour:a.getUTCHours(),minute:a.getUTCMinutes(),...o?{second:o}:{},utcOffsetMinutes:t.utcOffsetMinutes,latitude:t.latitude,longitude:t.longitude}}export{y as A,ae as C,O as D,T as E,C as M,D as O,F as S,P as T,L as _,Se as a,de as b,xe as c,be as d,I as f,H as g,me as h,Te as i,w as j,v as k,X as l,pe as m,Oe as n,$ as o,fe as p,Ee as r,Q as s,Ce as t,ge as u,ue as v,k as w,B as x,V as y};